career_history:
[{'company': 'CRED', 'title': 'Recommendation Systems Engineer', 'start_date': '2023-05-13', 'end_date': None, 'duration_months': 37, 'is_current': True, 'industry': 'Fintech', 'company_size': '1001-5000', 'description': 'Owned the ranking layer for an e-commerce search product, evolving it from a hand-tuned scoring function to a learning-to-rank model over 9 months. Designed the relevance labeling pipeline (mix of click-through data and explicit human judgments), the feature pipeline, and the training/eval workflow. Most of the work was infrastructure and data quality — the modeling part was almost the easy bit. Final model improved revenue-per-search by 12%.'}
 {'company': 'Mad Street Den', 'title': 'Search Engineer', 'start_date': '2019-02-03', 'end_date': '2023-05-13', 'duration_months': 52, 'is_current': False, 'industry': 'AI/ML', 'company_size': '201-500', 'description': 'Implemented a RAG-based customer support chatbot integrated with our existing ticketing system. Built the document ingestion pipeline (chunking, embedding via OpenAI embeddings, storing in Pinecone) and the answer-generation layer (initially GPT-4, then a fine-tuned smaller model for cost control). Designed the evaluation framework with both automatic metrics (BLEU, ROUGE) and human-in-the-loop quality scores. Deployment cut average ticket resolution time by 31% for the supported categories.'}
 {'company': 'Yellow.ai', 'title': 'NLP Engineer', 'start_date': '2018-07-31', 'end_date': '2019-01-27', 'duration_months': 6, 'is_current': False, 'industry': 'AI/ML', 'company_size': '201-500', 'description': 'Built a content recommendation system serving 10M+ users that combined collaborative filtering with content-based ranking. The system uses item-item similarity (via sentence-transformer embeddings) for cold starts and a gradient-boosted model trained on engagement signals for warm users. Most of my time went into the feature pipeline (~200 features) and the A/B testing infrastructure. The launch improved 7-day retention by 6% and time spent per session by 14%.'}]

