career_history:
[{'company': 'Zomato', 'title': 'Senior Machine Learning Engineer', 'start_date': '2024-04-07', 'end_date': None, 'duration_months': 26, 'is_current': True, 'industry': 'Food Delivery', 'company_size': '5001-10000', 'description': 'Built a RAG-based ranking pipeline serving 50M+ queries per month for an internal recruiter-facing search product. The architecture combined BM25 + dense retrieval (BGE embeddings, FAISS HNSW) with an LLM-based re-ranker on the top-50, falling back to a learning-to-rank model when latency budget was tight. Designed the offline evaluation framework from scratch — NDCG, MRR, recall@K calibrated against online A/B engagement metrics. Drove the migration over 4 months including the recruiter-feedback loop that surfaced reranking edge cases.'}
 {'company': 'Google', 'title': 'Staff Machine Learning Engineer', 'start_date': '2022-10-15', 'end_date': '2024-04-07', 'duration_months': 18, 'is_current': False, 'industry': 'Internet', 'company_size': '10001+', 'description': 'Built a RAG-based ranking pipeline serving 50M+ queries per month for an internal recruiter-facing search product. The architecture combined BM25 + dense retrieval (BGE embeddings, FAISS HNSW) with an LLM-based re-ranker on the top-50, falling back to a learning-to-rank model when latency budget was tight. Designed the offline evaluation framework from scratch — NDCG, MRR, recall@K calibrated against online A/B engagement metrics. Drove the migration over 4 months including the recruiter-feedback loop that surfaced reranking edge cases.'}
 {'company': 'Flipkart', 'title': 'Senior Machine Learning Engineer', 'start_date': '2019-04-27', 'end_date': '2022-10-08', 'duration_months': 42, 'is_current': False, 'industry': 'E-commerce', 'company_size': '10001+', 'description': 'Fine-tuned LLaMA-2-7B and Mistral-7B variants using LoRA and QLoRA for domain-specific candidate-JD matching. Built the data curation pipeline that generated 200K high-quality preference pairs from recruiter labels, plus the eval harness using both ranking metrics and human-quality scores. Deployed the model via BentoML on Kubernetes with sub-200ms p95 latency by quantizing to INT8 and batching at the request level. Cost per inference dropped from $0.04 with GPT-3.5-fallback to under $0.001.'}]

