[{'company': 'Locobuzz', 'title': 'NLP Engineer', 'start_date': '2024-10-04', 'end_date': None, 'duration_months': 20, 'is_current': True, 'industry': 'AI/ML', 'company_size': '51-200', 'description': 'Owned the ranking layer for an e-commerce search product, evolving it from a hand-tuned scoring function to a learning-to-rank model over 9 months. Designed the relevance labeling pipeline (mix of click-through data and explicit human judgments), the feature pipeline, and the training/eval workflow. Most of the work was infrastructure and data quality — the modeling part was almost the easy bit. Final model improved revenue-per-search by 12%.'}
 {'company': 'Yellow.ai', 'title': 'Machine Learning Engineer', 'start_date': '2021-12-12', 'end_date': '2024-09-27', 'duration_months': 34, 'is_current': False, 'industry': 'AI/ML', 'company_size': '201-500', 'description': 'Built a content recommendation system serving 10M+ users that combined collaborative filtering with content-based ranking. The system uses item-item similarity (via sentence-transformer embeddings) for cold starts and a gradient-boosted model trained on engagement signals for warm users. Most of my time went into the feature pipeline (~200 features) and the A/B testing infrastructure. The launch improved 7-day retention by 6% and time spent per session by 14%.'}
 {'company': 'Zoho', 'title': 'Senior Data Scientist', 'start_date': '2019-10-17', 'end_date': '2021-12-05', 'duration_months': 26, 'is_current': False, 'industry': 'SaaS', 'company_size': '10001+', 'description': 'Developed a semantic search feature for an internal knowledge base of ~500K documents. Used sentence-transformers (all-MiniLM-L6-v2 initially, later upgraded to bge-base) with FAISS for fast nearest-neighbor retrieval. Designed the query expansion module that handles vocabulary mismatch between user queries and document terms. Reported search-relevance improvement of 35% over the prior Elasticsearch BM25 setup, validated through human relevance judgments.'}]

